package app.manga.config;
import java.time.Duration;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.http.HttpMethod;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);}
 @Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.cors(Customizer.withDefaults()).csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/v1/manga/**","/api/v1/genres","/api/v1/reading-sources/**","/api/v1/auth/**","/actuator/health","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers(HttpMethod.OPTIONS,"/**").permitAll().anyRequest().authenticated()).logout(l->l.logoutUrl("/api/v1/auth/logout").logoutSuccessHandler((r,s,a)->s.setStatus(204))).build();}
 @Bean CorsConfigurationSource cors(@Value("${app.cors-origin}")String origin){var c=new CorsConfiguration();c.setAllowedOrigins(java.util.List.of(origin));c.setAllowedMethods(java.util.List.of("GET","POST","PATCH","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(java.util.List.of("Content-Type","Accept"));c.setAllowCredentials(true);c.setMaxAge(Duration.ofHours(1));var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/**",c);return source;}
}
